import {test} from 'node:test';import assert from 'node:assert/strict';import {Circle,Transform,Vec2,testOverlap} from 'planck';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
import {Simulation} from '../src/simulation/world';import {sizeSimulation} from '../src/simulation/roster';import {setSimulationArena} from '../src/simulation/arena-adapter';import {ARENAS,arenaList} from '../src/simulation/arenas';import {applyChaos} from '../src/chaos/registry';import {distributedSpawns,placeRoundSpawns,spawnCandidates} from '../server/arena-spawns';import {capture,restore} from '../src/simulation/state';import {navigationGraph,route} from '../server/navigation/geometry';
for(const a of arenaList) test(`${a.id}: seeded spread, actual clearance and stable supported starts for 2–8 frogs`,()=>{for(let count=2;count<=8;count++)for(let seed=1;seed<=12;seed++){const s=new Simulation();setSimulationArena(s,a.id);sizeSimulation(s,count);s.reset();const points=placeRoundSpawns(s,a.id,seed);assert.deepEqual(distributedSpawns(s,a.id,seed),points);for(let i=0;i<count;i++){const p=points[i];for(let j=0;j<i;j++)assert.ok(Math.hypot(p.x-points[j].x,p.y-points[j].y)>3,'separation');for(let b=s.world.getBodyList();b;b=b.getNext()){if(s.frogs.some(f=>f.body===b)||!b.isActive())continue;for(let fix=b.getFixtureList();fix;fix=fix.getNext())assert.ok(!testOverlap(Circle(s.tuning.frogRadius),0,fix.getShape(),0,Transform(Vec2(p.x,p.y),0),b.getTransform()),'terrain overlap');}}for(let t=0;t<300;t++)s.step();for(let i=0;i<count;i++)assert.ok(Vec2.distance(s.frogs[i].body.getPosition(),Vec2(points[i].x,points[i].y))<.15,'stable until countdown ends');if(count===2)assert.ok(Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y)>15);}const s=new Simulation();setSimulationArena(s,a.id);sizeSimulation(s,8);s.reset();assert.ok(new Set(Array.from({length:12},(_,i)=>JSON.stringify(distributedSpawns(s,a.id,i)))).size>8);assert.ok(distributedSpawns(s,a.id,5).some(p=>p.source>0));sizeSimulation(s,2);assert.ok(new Set(Array.from({length:24},(_,i)=>JSON.stringify(distributedSpawns(s,a.id,i)))).size>=8,'two-player variety');});
for(const ids of [['gravity_flip'],['crumble_time'],['tilt_a_frog'],['pogo_panic'],['windy_weather'],['bubble_trouble'],['sticky_frogs'],['mega_frogs','tilt_a_frog'],['tiny_trouble','crumble_time'],['gravity_flip','sticky_frogs','mega_tongues']])test(`all arenas: authoritative valid reset/snapshot with ${ids.join('+')}`,()=>{for(const a of arenaList){const s=new Simulation();setSimulationArena(s,a.id);sizeSimulation(s,8);applyChaos(s,ids);s.reset();s.arenaChaos.paused=true;s.frogChaos.paused=true;const points=placeRoundSpawns(s,a.id,123);for(let t=0;t<240;t++)s.step();if(ids.includes('tilt_a_frog')){assert.ok(points.every(p=>p.source===0));assert.ok(s.frogs.every((f,i)=>Math.abs(f.body.getPosition().x-points[i].x)<.05));}s.arenaChaos.paused=false;s.frogChaos.paused=false;for(let t=0;t<780;t++)s.step();assert.ok(s.frogs.every(f=>{const p=f.body.getPosition();return Number.isFinite(p.x+p.y)&&p.x>=0&&p.x<=40&&p.y>=0&&p.y<=22.5;}));const c=new Simulation();setSimulationArena(c,a.id);applyChaos(c,ids);restore(c,capture(s));assert.deepEqual(capture(c),capture(s));}});
